/bin/zsh -lc 'which pdftotext; which mutool; which tesseract; which libreoffice; which python3; for f in $(find workspace -name '"'*.pdf'); do echo ==== \""'$f"; pdftotext "$f" - 2>&1 | head -30; done; python3 - <<'"'PY'
import zipfile,glob
for f in glob.glob('workspace/**/*.xlsx',recursive=True):
 print('\\n====',f)
 with zipfile.ZipFile(f) as z:
  print('files',z.namelist())
  for n in ['xl/sharedStrings.xml','xl/worksheets/sheet1.xml','docProps/core.xml']:
   if n in z.namelist(): print(n,z.read(n).decode('utf-8','replace')[:12000])
PY"

